          ],
          "condicoes": [
            "operações de offloading com navios aliviadores convencionais",
            "terminais de aproamento variável"
          ],
          "limites": [
            "o trecho é descritivo de configurações históricas/iniciais",
            "a continuação sobre ausência de facilidades para estiva está truncada no material fornecido"
