          ]
        },
        {
          "proposicao": "A proposta de setor operacional atribuída a LERSTAD parte da premissa de não usar hawser, busca maior distância entre unidade de produção e embarcação de alívio para reduzir exposição à colisão direta e adota lógica de posicionamento com dois pontos de pivotamento para evitar alinhamento longitudinal do NADP com o FPSO.",
          "trechos": [
            "E6cdf85c6294e4a38:1398:2097",
            "E6cdf85c6294e4a38:2097:2365"
          ],
          "condicoes": [
            "setor operacional proposto para NADP em alívio indireto de FPSO geoestacionário",
            "diretriz de simplificação operacional atribuída a companhias operadoras no Mar do Norte"
          ],
          "limites": [
            "trata-se de proposta contextualizada ao estudo e ao Mar do Norte, não requisito brasileiro",
            "o trecho não demonstra sozinho desempenho operacional em campo"
          ]
        }
